(function(root){
'use strict';
function mount(panel,options={}){
 const model=root.PLGoalModel.create(root.PLGoalSample),esc=root.MatchWorkspace?.esc||MatchWorkspace.esc;
 const node=id=>panel.querySelector('#pl-g-'+id),text=(el,value)=>{if(el.textContent!==value)el.textContent=value;};
 const format=t=>{const mins=Math.floor(t/60),secs=(t%60).toFixed(2).padStart(5,'0');return String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0')+':'+secs;};
 let cursor=model.initial,selected='wide-B1',timer=null,generation=0,active=false;
 const displayActor=p=>p.id==='wide-GK'?'Chelsea goalkeeper':p.id==='corner-B1'?'Brentford corner taker':p.id==='wide-B1'?'Brentford player · shirt 27 observed':'Unidentified '+(p.team==='brentford'?'Brentford':'Chelsea')+' player';
 const displayTag=p=>p.id==='wide-GK'?'GK':p.id==='corner-B1'?'24':p.id==='wide-B1'?'27':'?';
 const questions=['Where is this player?','Where is the ball?','What is visible here?','What happened before this moment?','What supports this?','What is missing here?'];
 panel.innerHTML=`<div class="goal-context"><div><span class="eyebrow">FIRST-GOAL PASSAGE</span><h2>On the pitch</h2><p>Brentford–Chelsea · Manual video reconstruction · No live feed</p></div><details class="goal-sources"><summary>Sources & method ↗</summary><p>Existing official replay, source clip 01:01:48–01:01:59. Twenty-four manually placed layouts include 19 wide-shot anchors at 0.2-second spacing. The 38 reviewed stills include adjacent-frame camera-cut checks; this is sampled review, not continuous video review.</p><p>Goal, six-yard box, penalty-area and touchline landmarks guide broad body-base placements. The attacking third is a schematic crop, with no camera calibration or metric coordinates. The selected marker’s shaded area indicates broad layout uncertainty, not statistical confidence.</p><p>Internal anonymous IDs belong to this camera shot. Unidentified players display ?; 24/27 are observed shirt numbers and GK identifies only the visible goalkeeper role. The roster lists 16 tracklets across two shots, not 16 distinct identified players or a full XI. Shirt 27 is readable at one wide-shot point; names remain unjoined. The corner taker’s shirt 24 belongs only to the corner shot.</p><p>Solid markers: manual reviewed-frame estimates. Dashed markers: interpolation between adjacent same-track/same-shot frames, including a future endpoint. Playback shows 0.2-second source-clock steps at 1×; no player position crosses a cut or ambiguous interval.</p><p>The ball is independently available only at reviewed frames. An airborne marker is an apparent schematic projection, with height and ground position unknown. No held/interpolated ball, contact, scorer/assist, running path, speed or distance is supplied.</p><p>Captured clock and score appear only at exact frames; no universal match-clock fit or goal second is inferred. Earlier facts wait for their last supporting frame. Source media is not loaded into this prototype.</p><p><a href="${esc(model.source.url)}" target="_blank" rel="noopener">Official full recording ↗</a> · Opens source material beyond this bounded passage.</p><details><summary>Static receipts & limits</summary><pre tabindex="0">${esc(JSON.stringify(model.source,null,2))}</pre><ul>${model.limits.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details></details></div>
 <div class="goal-layout"><section class="goal-pitch-panel" aria-label="First-goal pitch replay"><div class="goal-pitch-meta"><strong>Attacking third · schematic</strong><span id="pl-g-clock"></span></div><div class="goal-pitch" id="pl-g-field" role="group" aria-label="Schematic attacking third. Goal at left, far touchline above, near touchline below. Select a player or use the roster."><svg viewBox="0 0 32 100" preserveAspectRatio="none" aria-hidden="true"><path d="M0 0H32V100H0Z M0 20H16V80H0 M0 39H6V61H0 M16 35A12 15 0 0 1 16 65 M0 44H-.8V56H0"/></svg><span id="pl-g-uncertainty" class="goal-uncertainty" hidden aria-hidden="true"></span>${model.participants.map(p=>`<button class="goal-marker ${esc(p.team)}" id="pl-g-marker-${p.id}" data-goal-player="${esc(p.id)}" aria-pressed="false" hidden><span>${esc(displayTag(p))}</span></button>`).join('')}<span id="pl-g-ball" class="goal-ball" role="img" hidden></span><p class="goal-empty" id="pl-g-empty" hidden>Positions unknown<br><small>Unreviewed interval or camera change</small></p></div><div class="goal-legend"><span><i class="goal-key brentford"></i> Brentford</span><span><i class="goal-key chelsea"></i> Chelsea</span><span><i class="goal-key ball"></i> Ball when supported</span></div><p class="goal-estimate-note">All placements are estimates. ? = unidentified player · 24 / 27 are observed shirts · GK = goalkeeper</p><p id="pl-g-coverage" class="goal-readout"></p><label class="sr-only" for="pl-g-player">Selected visible track</label><select id="pl-g-player">${model.participants.map(p=>`<option value="${p.id}">${esc(displayActor(p))}</option>`).join('')}</select><p id="pl-g-position" class="goal-readout"></p><p id="pl-g-ball-status" class="goal-readout"></p><div class="goal-transport"><label for="pl-g-range">Source clip <strong id="pl-g-time"></strong></label><input id="pl-g-range" type="range" min="${model.start}" max="${model.end}" step="any" value="${cursor}"><div class="goal-bands" aria-label="Sparse corner setup, camera gap, wide action, final gap"><span style="flex:6.4" title="Sparse setup; positions mostly unknown"></span><span class="gap" style="flex:.6" title="Camera gap"></span><span class="action" style="flex:3.6" title="Wide action"></span><span class="gap" style="flex:.4" title="Camera change and close-up"></span></div><div class="goal-controls"><button id="pl-g-play" aria-pressed="false">▶ Play</button><button id="pl-g-start">← Start</button><button id="pl-g-action">Wide action</button><button id="pl-g-previous">← Previous frame</button><button id="pl-g-next">Next frame →</button><button id="pl-g-end">End →</button><button id="pl-g-gap">Inspect camera gap</button></div><p id="pl-g-status" role="status" aria-live="polite"></p></div></section>
 <section class="goal-roster" aria-label="Visible source tracks"><div><h3>Players in view</h3><span id="pl-g-roster-clock"></span></div><p>Select a visible track · Unknown positions stay in the list</p><table><thead><tr><th scope="col">Visible track</th><th scope="col">At this cursor</th></tr></thead><tbody>${model.participants.map(p=>`<tr id="pl-g-row-${p.id}"><th scope="row"><button data-goal-player="${p.id}" aria-pressed="false"><span class="goal-roster-tag ${p.team}">${esc(displayTag(p))}</span>${esc(displayActor(p))}</button></th><td id="pl-g-quality-${p.id}"></td></tr>`).join('')}</tbody></table></section></div>
 <section class="goal-conversation conversation" aria-label="Questions about this pitch moment"><div class="conversation-bar"><div><span class="avatar" aria-hidden="true">↗</span><div><strong>This moment on the pitch</strong><small>Cursor and selected player · Local answers · No AI</small></div></div></div><div id="pl-g-thread" role="log" aria-live="polite"></div><div class="goal-suggestions">${questions.map(q=>`<button data-goal-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><form id="pl-g-composer"><label class="sr-only" for="pl-g-draft">Question about this pitch moment</label><input id="pl-g-draft" placeholder="Ask about this moment or player…" autocomplete="off"><button type="submit" aria-label="Send question">↑</button></form><p id="pl-g-answer-status">Answers use the current cursor and selected visible track.</p></section>`;
 function clear(){node('thread').replaceChildren();text(node('answer-status'),'Answers use the current cursor and selected visible track.');}
 function stop(){generation++;if(timer!==null)clearInterval(timer);timer=null;text(node('play'),'▶ Play');node('play').setAttribute('aria-pressed','false');text(node('status'),'Paused at source '+format(cursor)+'.');}
 function paint(){
  const v=model.view(cursor),actor=v.players.find(p=>p.id===selected),position=actor.position;
  node('range').value=String(cursor);node('range').setAttribute('aria-valuetext',`Source ${format(cursor)}. ${v.count} visible track positions. ${v.frame?'Captured match clock '+v.frame.clock:'Captured match clock unknown'}.`);
  node('player').value=selected;text(node('time'),format(cursor));text(node('clock'),v.frame?`Captured ${v.frame.clock} · ${v.frame.score.join('–')}`:'Captured clock / score unknown');text(node('roster-clock'),format(cursor));
  text(node('coverage'),`${v.count} / 16 visible tracks placed · ${v.frame?'Reviewed-frame estimates':v.count?'Interpolated estimates':'Positions unknown'}${v.shot?' · '+(v.shot==='wide'?'Wide goalmouth view':'Corner-side view'):''}`);
  text(node('position'),displayActor(actor)+': '+(position?(position.kind==='reviewed_estimate'?'manual reviewed-frame estimate':'interpolated estimate · neighbouring future endpoint used'):'position unknown · no carry across gaps'));
  text(node('ball-status'),v.ball?'Ball: reviewed-frame schematic projection · height / ground position unknown':'Ball: position unknown · independent of player coverage');
  for(const p of v.players){const marker=node('marker-'+p.id),row=node('row-'+p.id),button=row.querySelector('button');if(!p.available&&document.activeElement===marker)button.focus({preventScroll:true});marker.hidden=!p.available;marker.setAttribute('aria-pressed',String(p.id===selected));button.setAttribute('aria-pressed',String(p.id===selected));row.classList.toggle('selected',p.id===selected);text(node('quality-'+p.id),p.available?(p.position.kind==='reviewed_estimate'?'Estimated':'Interpolated'):'Unknown');if(p.available){marker.style.left=(p.position.x/32*100)+'%';marker.style.top=p.position.y+'%';marker.dataset.kind=p.position.kind;marker.setAttribute('aria-label',displayActor(p)+'. '+(p.position.kind==='reviewed_estimate'?'Manual reviewed-frame estimate.':'Interpolated estimate using a future frame.'));}}
  const halo=node('uncertainty');halo.hidden=!position;if(position){halo.style.left=position.x/32*100+'%';halo.style.top=position.y+'%';}
  const ball=node('ball');ball.hidden=!v.ball;if(v.ball){ball.style.left=v.ball.x/32*100+'%';ball.style.top=v.ball.y+'%';ball.setAttribute('aria-label','Ball: apparent schematic projection. Height and ground position unknown. Reviewed frame '+v.ball.evidenceIds.join('/'));}
  node('empty').hidden=!v.gap;node('play').disabled=cursor>=model.end;node('previous').disabled=model.adjacent(cursor,-1)===null;node('next').disabled=model.adjacent(cursor,1)===null;
 }
 function seek(value){stop();cursor=model.clamp(value);clear();paint();text(node('status'),'Paused at source '+format(cursor)+(model.view(cursor).gap?'. Positions unknown.':'.'));}
 function select(id){if(!model.participants.some(p=>p.id===id))return;stop();selected=id;clear();paint();text(node('status'),displayActor(model.participants.find(p=>p.id===selected))+' selected.');}
 function run(){if(!active||cursor>=model.end)return;stop();clear();const token=generation,origin=cursor,started=root.performance?.now?.()??Date.now();timer=setInterval(()=>{if(!active||token!==generation)return;const elapsed=((root.performance?.now?.()??Date.now())-started)/1000;cursor=Math.min(model.end,Math.max(origin,Math.round((model.start+Math.floor(((origin-model.start)+elapsed+1e-7)/.2)*.2)*100)/100));paint();if(cursor>=model.end){stop();text(node('status'),'End of the bounded passage. Playback stopped.');}},50);text(node('play'),'Ⅱ Pause');node('play').setAttribute('aria-pressed','true');text(node('status'),'Playing at 1× in 0.2-second source-clock steps. Ball appears only at supported samples.');}
 function ask(q){if(!String(q).trim())return;stop();const answer=model.answer(cursor,selected,q),name=displayActor(model.participants.find(p=>p.id===selected)),stamp=`PITCH NOTE · SOURCE ${format(cursor)} · ${name}`;node('thread').insertAdjacentHTML('beforeend',MatchWorkspace.message(q,true,stamp,'')+MatchWorkspace.message(answer.text.replace(model.participants.find(p=>p.id===selected).label,name).replace('B/C tags are local anonymous labels, not shirt numbers.','Unidentified players show ?. Other labels are observed shirts or goalkeeper role.'),false,stamp,'Manual video reconstruction · local answer'+(answer.evidenceIds.length?' · '+answer.evidenceIds.join(' / '):'')));text(node('answer-status'),'Answer at '+format(cursor)+' · '+name+'.');}
 node('range').addEventListener('input',e=>seek(Number(e.target.value)));node('player').addEventListener('change',e=>select(e.target.value));node('composer').addEventListener('submit',e=>{e.preventDefault();ask(node('draft').value);node('draft').value='';});
 panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.goalPlayer)select(b.dataset.goalPlayer);else if(b.dataset.goalQuestion)ask(b.dataset.goalQuestion);else if(b.id==='pl-g-play'){if(timer!==null)stop();else run();}else if(b.id==='pl-g-start')seek(model.start);else if(b.id==='pl-g-action')seek(model.initial);else if(b.id==='pl-g-previous'||b.id==='pl-g-next'){const t=model.adjacent(cursor,b.id==='pl-g-previous'?-1:1);if(t!==null)seek(t);}else if(b.id==='pl-g-end')seek(model.end);else if(b.id==='pl-g-gap')seek(3714.94);});
 if(options.onOfficial){panel.insertAdjacentHTML('afterbegin','<div class="goal-record-link"><button id="pl-g-official-action" class="text-button">Official match record ↗</button><span>Completed-match facts · includes later events</span></div>');node('official-action').addEventListener('click',()=>{stop();clear();options.onOfficial();});}
 function deactivate(){active=false;stop();clear();}function activate(){active=true;stop();clear();paint();}
 stop();paint();return {activate,deactivate,stop:()=>{stop();clear();},showPassage:()=>{seek(model.initial);node('play').focus({preventScroll:true});},focusRecordAction:()=>node(options.onOfficial?'official-action':'play').focus({preventScroll:true})};
}
root.PLGoalPitch={mount};
})(window);
